cd /tmp/sv-95c66bf1883a44279e4313d886ff1075/symbols && \
# Get dynamic symbols from libmonosgen-2.0.so and find functions near our addresses
# Addresses: 0x222098, 0x222234, 0x19bac0, 0x19bc14
readelf -W --dyn-syms libmonosgen-2.0.so | awk '$4 == "FUNC" && $2 != "0000000000000000"' | sort -k2 | grep -v "^$" > mono_syms.txt
wc -l mono_syms.txt
echo "---"
# Find symbols near each address
for addr in 0x222098 0x222234 0x19bac0 0x19bc14; do
  echo "=== Looking for $addr ==="
  awk -v addr="$addr" '
    BEGIN { target = strtonum(addr); best_name=""; best_addr=0; best_size=0 }
    {
      sym_addr = strtonum("0x" $2);
      sym_size = strtonum($3);
      if (sym_addr <= target && sym_addr > best_addr) {
        best_addr = sym_addr;
        best_name = $8;
        best_size = sym_size;
      }
    }
    END {
      offset = target - best_addr;
      printf "  %s+0x%x (symbol at 0x%x, size %d)\n", best_name, offset, best_addr, best_size
    }
  ' mono_syms.txt
done

