{"command": "cd /tmp/sv-95c66bf1883a44279e4313d886ff1075/symbols && \
# Find all symbols in the range near our target addresses
python3 -c "
import subprocess, re

# Read all dynsym
result = subprocess.run(['readelf', '-W', '--dyn-syms', 'libmonosgen-2.0.so'], capture_output=True, text=True)
syms = []
for line in result.stdout.splitlines():
    parts = line.split()
    if len(parts) >= 8 and parts[3] == 'FUNC':
        try:
            addr = int(parts[1], 16)
            size = int(parts[2])
            name = parts[7]
            if addr > 0:
                syms.append((addr, size, name))
        except: pass
syms.sort()

targets = [0x222098, 0x222234, 0x19bac0, 0x19bc14]
for t in targets:
    # Find surrounding symbols
    prev = None
    nxt = None
    for s in syms:
        if s[0] <= t:
            prev = s
        elif nxt is None:
            nxt = s
    print(f'Address 0x{t:x}:')
    if prev:
        off = t - prev[0]
        print(f'  prev: {prev[2]} @ 0x{prev[0]:x} (size={prev[1]}, offset=+0x{off:x})')
    if nxt:
        print(f'  next: {nxt[2]} @ 0x{nxt[0]:x} (size={nxt[1]})')
    print()
"", "description": "Find surrounding symbols for all addresses"}
